const char* indexHTML = "<!DOCTYPE html><html><head><title>Apex Sims</title><style>@import url('https://fonts.googleapis.com/css2?family=Zen+Dots&display=swap');html,body {margin: 0px;padding: 0px;min-width: 1140px;background: whitesmoke;}button {appearance: none;background-color: transparent;border: 0.125em solid #1A1A1A;border-radius: 0.9375em;width: 100%;color: #3B3B3B;cursor: pointer;display: inline-block;font-family: Roobert, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Helvetica, Arial, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\";font-size: 2vh;font-weight: 600;line-height: normal;margin-top: 2vh;outline: none;padding: 1em 2.3em;text-align: center;text-decoration: none;transition: all 300ms cubic-bezier(.23, 1, 0.32, 1);user-select: none;-webkit-user-select: none;touch-action: manipulation;will-change: transform;}button:disabled {pointer-events: none;}button:hover {color: #fff;background-color: #1A1A1A;box-shadow: rgba(0, 0, 0, 0.25) 0 8px 15px;transform: translateY(-2px);}button:active {box-shadow: none;transform: translateY(0);}#title {margin: 0px;font-size: 10vh;font-family: \"Zen Dots\", sans-serif;font-weight: 400;font-style: normal;text-align: center;padding-top: 1vh;color: whitesmoke;}#header {margin-bottom: 0.5%;width: 100%;height: 10vh;padding-bottom: 4vh;background: #2A7B9B;background: linear-gradient(160deg, rgba(42, 123, 155, 1) 0%, rgba(87, 199, 133, 1) 50%, rgba(237, 221, 83, 1) 100%);}#bay1,#bay3 {float: left;}#bay2,#bay4 {float: right;}.baynumber {float: left;width: fit-content;margin: 0;padding-left: 5%;font-size: 35vh;font-family: Roobert, -apple-system, BlinkMacSystemFont, \"Segoe UI\", Helvetica, Arial, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\";opacity: 25%;}.controlpannel {height: 40vh;width: 48.5%;margin: 0.5%;background-color: rgb(144, 168, 174);border: 0.125em solid rgb(122, 142, 147);border-radius: 0.9375em;}.buttonbox {float: right;width: 25%;margin-top: 1%;margin-right: 5%;}.timer {float: left;width: 30vmin;height: 30vmin;margin-top: 4%;margin-left: 7%;border: 1vh solid transparent;border-radius: 50%;background: linear-gradient(rgb(122, 142, 147), rgb(122, 142, 147)) content-box no-repeat,conic-gradient(transparent 100%, 0, green) border-box;text-align: center;}.time {margin-top: 40%;font-size: 5vh;color: #3B3B3B;}</style></head><body><div id=\"header\"><h1 id=\"title\">APEX SIMS</h1></div><div class=\"controlpannel\" id=\"bay1\"><h2 class=\"baynumber\">1</h2><div class=\"timer\" id=\"timer1\"><h3 class=\"time\" id=\"time1\">Time Over</h3></div><div class=\"buttonbox\"><button id=\"button11\" onclick=\"control(1, 1800)\">Start 30 Min</button><button id=\"button12\" onclick=\"control(1, 3600)\">Start 60 Min</button><button id=\"button13\" onclick=\"control(1, 0)\">End Time</button><button id=\"button14\" onclick=\"secondMenu(1, 'button11', 'button12', 'button13', 'button14')\">More</button></div></div><div class=\"controlpannel\" id=\"bay2\"><h2 class=\"baynumber\">2</h2><div class=\"timer\" id=\"timer2\"><h3 class=\"time\" id=\"time2\">Time Over</h3></div><div class=\"buttonbox\"><button id=\"button21\" onclick=\"control(2, 1800)\">Start 30 Min</button><button id=\"button22\" onclick=\"control(2, 3600)\">Start 60 Min</button><button id=\"button23\" onclick=\"control(2, 0)\">End Time</button><button id=\"button24\" onclick=\"secondMenu(2, 'button21', 'button22', 'button23', 'button24')\">More</button></div></div><div class=\"controlpannel\" id=\"bay3\"><h2 class=\"baynumber\">3</h2><div class=\"timer\" id=\"timer3\"><h3 class=\"time\" id=\"time3\">Time Over</h3></div><div class=\"buttonbox\"><button id=\"button31\" onclick=\"control(3, 1800)\">Start 30 Min</button><button id=\"button32\" onclick=\"control(3, 3600)\">Start 60 Min</button><button id=\"button33\" onclick=\"control(3, 0)\">End Time</button><button id=\"button34\" onclick=\"secondMenu(3, 'button31', 'button32', 'button33', 'button34')\">More</button></div></div><div class=\"controlpannel\" id=\"bay4\"><h2 class=\"baynumber\">4</h2><div class=\"timer\" id=\"timer4\"><h3 class=\"time\" id=\"time4\">Time Over</h3></div><div class=\"buttonbox\"><button id=\"button41\" onclick=\"control(4, 1800)\">Start 30 Min</button><button id=\"button42\" onclick=\"control(4, 3600)\">Start 60 Min</button><button id=\"button43\" onclick=\"control(4, 0)\">End Time</button><button id=\"button44\" onclick=\"secondMenu(4, 'button41', 'button42', 'button43', 'button44')\">More</button></div></div><script>const firstMenu = (bay, button1, button2, button3, button4) => {document.getElementById(button1).outerHTML = `<button id=\"${button1}\" onclick=\"control(${bay}, 1800)\">Start 30 Min</button>`;document.getElementById(button2).outerHTML = `<button id=\"${button2}\" onclick=\"control(${bay}, 3600)\">Start 60 Min</button>`;document.getElementById(button3).outerHTML = `<button id=\"${button3}\" onclick=\"control(${bay}, 0)\">End Time</button>`;document.getElementById(button4).outerHTML = `<button id=\"${button4}\" onclick=\"secondMenu(${bay}, '${button1}', '${button2}', '${button3}', '${button4}')\">More</button>`;};const secondMenu = (bay, button1, button2, button3, button4) => {document.getElementById(button1).outerHTML = `<button id=\"${button1}\" onclick=\"control(${bay}, +prompt('Enter custom time in minutes') * 60)\">Edit Time</button>`;document.getElementById(button2).outerHTML = `<button id=\"${button2}\" onclick=\"\">Manual Power</button>`;document.getElementById(button3).outerHTML = `<button id=\"${button3}\" onclick=\"\">Update Device State</button>`;document.getElementById(button4).outerHTML = `<button id=\"${button4}\" onclick=\"firstMenu(${bay}, '${button1}', '${button2}', '${button3}', '${button4}')\">Back</button>`;};let time_original = [0, 0, 0, 0];let time = [0, 0, 0, 0];const control = (bay, set_time) => {time_original[bay - 1] = set_time;time[bay - 1] = set_time;const xhr = new XMLHttpRequest();xhr.open(\"POST\", \"/control\");xhr.setRequestHeader(\"Content-Type\", \"application/json; charset=UTF-8\");const body = JSON.stringify({bay: bay,time: set_time,});xhr.onload = () => {if (xhr.readyState != 4 && xhr.status != 201) {    console.log(`Error: ${xhr.status}`);}};xhr.send(body);};const updateStatus = () => {const xhr = new XMLHttpRequest();xhr.open(\"GET\", \"/status\");xhr.setRequestHeader(\"Content-Type\", \"text/plain; charset=UTF-8\");const body = \"Status requested\";xhr.onload = () => {if (xhr.readyState == 4 && xhr.status == 201) {    const response = JSON.parse(xhr.responseText);    for (let i = 0; i < response.time.set_time; i++) {        time_original[i] = response.time_original[i];        time[i] = response.time[i];    }} else {    console.log(`Error: ${xhr.status}`);}};xhr.send(body);};updateStatus();let timeout = 600;const countdownTimer = setInterval(() => {document.getElementById(\"time1\").innerHTML = (time[0] > 0 ? Math.floor(time[0]-- / 60) + \":\" + (Math.round(time[0] % 60) >= 10 ? Math.round(time[0] % 60) : \"0\" + Math.round(time[0] % 60)) : \"Time Over\");document.getElementById(\"timer1\").style.background = \"linear-gradient(rgb(122, 142, 147), rgb(122, 142, 147)) content-box no-repeat, conic-gradient(transparent \" + (time_original[0] != 0 ? ((1 - (time[0] / time_original[0])) * 100) : 100) + \"%, 0, green) border-box\";document.getElementById(\"time2\").innerHTML = (time[1] > 0 ? Math.floor(time[1]-- / 60) + \":\" + (Math.round(time[1] % 60) >= 10 ? Math.round(time[1] % 60) : \"0\" + Math.round(time[1] % 60)) : \"Time Over\");document.getElementById(\"timer2\").style.background = \"linear-gradient(rgb(122, 142, 147), rgb(122, 142, 147)) content-box no-repeat, conic-gradient(transparent \" + (time_original[1] != 0 ? ((1 - (time[1] / time_original[1])) * 100) : 100) + \"%, 0, green) border-box\";document.getElementById(\"time3\").innerHTML = (time[2] > 0 ? Math.floor(time[2]-- / 60) + \":\" + (Math.round(time[2] % 60) >= 10 ? Math.round(time[2] % 60) : \"0\" + Math.round(time[2] % 60)) : \"Time Over\");document.getElementById(\"timer3\").style.background = \"linear-gradient(rgb(122, 142, 147), rgb(122, 142, 147)) content-box no-repeat, conic-gradient(transparent \" + (time_original[2] != 0 ? ((1 - (time[2] / time_original[2])) * 100) : 100) + \"%, 0, green) border-box\";document.getElementById(\"time4\").innerHTML = (time[3] > 0 ? Math.floor(time[3]-- / 60) + \":\" + (Math.round(time[3] % 60) >= 10 ? Math.round(time[3] % 60) : \"0\" + Math.round(time[3] % 60)) : \"Time Over\");document.getElementById(\"timer4\").style.background = \"linear-gradient(rgb(122, 142, 147), rgb(122, 142, 147)) content-box no-repeat, conic-gradient(transparent \" + (time_original[3] != 0 ? ((1 - (time[3] / time_original[3])) * 100) : 100) + \"%, 0, green) border-box\";timeout--;if (timeout == 0) {updateStatus();timeout = 600;}}, 1000);</script></body></html>";

const char* configHTML = "<!DOCTYPE html><html><head><title>Configuration</title></head><body><h1>Configuration</h1><h2>Wifi Network</h2><p id=\"ssid\">SSID: Loading...</p><button id=\"wifibutton\" onclick=\"sendData()\">Change wifi network</button><script>const xhr = new XMLHttpRequest();xhr.open(\"GET\", \"/wifi\");xhr.setRequestHeader(\"Content-Type\", \"text/plain; charset=UTF-8\");const body = \"Data requested\";xhr.onload = () => {if (xhr.readyState == 4 && xhr.status == 201) {const response = JSON.parse(xhr.responseText);ssid = response.ssid;document.getElementById(\"ssid\").innerHTML = \"SSID: \" + ssid;} else {console.log(`Error: ${xhr.status}`);}};xhr.send(body);  const sendData = () => {const xhr = new XMLHttpRequest();xhr.open(\"POST\", \"/changewifi\");xhr.setRequestHeader(\"Content-Type\", \"application/json; charset=UTF-8\");const body = JSON.stringify({ssid: \"Pixel_7634\",password: \"Pixy@4aa\",});xhr.onload = () => {if (xhr.readyState != 4 && xhr.status != 201) {console.log(`Error: ${xhr.status}`);}};xhr.send(body);location.reload();};</script></body></html>";